"""Independent reference implementations and a brute-force optimum."""
import bisect
import ipaddress

U = 1 << 128
WIDTH = (16, 8, 4)
LANES = (4, 8, 16)


def text_of(value):
    return str(ipaddress.IPv6Address(value))


def reference_runs(routes):
    entries = [(s, l, h) for (s, l), h in routes.items()]
    bounds = {0}
    for s, l, _h in entries:
        bounds.add(s)
        if l > 0:
            end = s + (1 << (128 - l))
            if end < U:
                bounds.add(end)
    out = []
    for b in sorted(bounds):
        best, bestlen = None, -1
        for s, l, h in entries:
            if s <= b < s + (1 << (128 - l)) and l > bestlen:
                bestlen, best = l, h
        hop = best if bestlen >= 0 else None
        if out and out[-1][1] == hop:
            continue
        out.append((b, hop))
    if not out:
        out = [(0, None)]
    return ([x[0] for x in out], [x[1] for x in out])


def compositions(total, parts):
    if parts == 1:
        yield (total,)
        return
    for head in range(1, total - parts + 2):
        for rest in compositions(total - head, parts - 1):
            yield (head,) + rest


def pareto(triples):
    """Keep the (work, pages, resident) frontier; drops dominated options."""
    triples.sort()
    out = []
    for work, pages, resident in triples:
        dominated = False
        for w2, p2, r2 in out:
            if w2 <= work and p2 <= pages and r2 <= resident:
                dominated = True
                break
        if dominated:
            continue
        out = [x for x in out if not (work <= x[0] and pages <= x[1]
                                      and resident <= x[2])]
